export default {
  id: 'pricing',
  name: 'Pricing',
  version: '1.0.0',
  onLoad(ctx: import('../../kernel/types').PluginContext) {
    ctx.register({
      kind: 'service',
      service: {
        id: 'pricing',
        instance: {
          total: (n: number): number => n * 21,
        },
      },
    });

    ctx.register({
      kind: 'tool',
      tool: {
        name: 'quote_total',
        version: '1.0.0',
        description: 'Return n*21 using the pricing service.',
        permissions: [],
        sideEffect: 'none',
        parameters: {
          type: 'object',
          properties: {
            n: { type: 'number' },
          },
          required: ['n'],
        },
        outputSchema: {
          type: 'object',
          properties: {
            total: { type: 'number' },
          },
          required: ['total'],
        },
        async handler(args: unknown) {
          const { n } = args as { n: number };
          const service = ctx.inject('service:pricing').value as {
            total: (n: number) => number;
          };
          return { ok: true, data: { total: service.total(n) } };
        },
      },
    });
  },
};

